pub fn create(destination_dir: bun.FD, tmpfilename: [:0]const u8) bun.sys.Maybe(Tmpfile) {
            const perm: i32 = 420;
            var tmpfile = Tmpfile{ .destination_dir = destination_dir, .tmpfilename = tmpfilename };
            _ = &tmpfile;
            open: while (true) {
                if (comptime allow_tmpfile) {
                    switch (bun.sys.openat(destination_dir, ".", ((O.WRONLY | O.TMPFILE) | O.CLOEXEC), perm)) {
.result => |fd| {
tmpfile.fd = (switch (bun.sys.makeLibUVOwnedFD(fd, .open, .close_on_fail)) {
.result => |owned_fd| owned_fd,
.err => |e| {
return .{ .err = e };
},
});
                    break :open;
},
.err => |e| {
switch (e.getErrno()) {
.INVAL, .OPNOTSUPP, .NOSYS => {
tmpfile.using_tmpfile = false;
},
else => {
return .{ .err = e };
},
}
},
}
                }
                tmpfile.fd = (switch (bun.sys.openat(destination_dir, tmpfilename, (((O.CREAT | O.EXCL) | O.CLOEXEC) | O.WRONLY), perm)) {
.result => |fd| (switch (fd.makeLibUVOwnedForSyscall(.open, .close_on_fail)) {
.result => |owned_fd| owned_fd,
.err => |e| {
return .{ .err = e };
},
}),
.err => |e| {
return .{ .err = e };
},
});
                break :open;
            }
            return .{ .result = tmpfile };
    }

pub fn finish(self: *Tmpfile, destname: [:0]const u8) !void {
            if (comptime allow_tmpfile) {
                if (self.using_tmpfile) {
                    var retry = true;
                    _ = &retry;
                    const basename: [:0]const u8 = (blk: {
                    break :blk @ptrCast(std.fs.path.basename(destname));

});
                    while (retry) {
                        const ret = bun.sys.linkatTmpfile(self.fd, self.destination_dir, basename);
                        switch (ret) {
.result => {
return;
},
.err => |e| {
if (((e.getErrno() == .EXIST) and retry)) {
                            _ = bun.sys.unlinkat(self.destination_dir, basename);
                            retry = false;
                            continue;
                        } else {
                            _ = try ret.unwrap();
                            return;
                        }
},
}
                    }
                }
            }
            _ = try bun.sys.moveFileZWithHandle(self.fd, self.destination_dir, self.tmpfilename, self.destination_dir, destname);
    }
};

const O = bun.O;
const allow_tmpfile = false;
